import torch
sd = torch.load('/app/adapter_cache/adapter_model.bin', map_location='cpu')
# Count lora keys per layer
layers = {}
for k in sd:
    if 'lora' in k:
        # extract layer number
        parts = k.split('.')
        for i, p in enumerate(parts):
            if p.startswith('layer.'):
                layer = p
                break
        layers[layer] = layers.get(layer, 0) + 1
for k in sorted(layers):
    print(k, layers[k])
